44	import java.util.ArrayList;
45	
46	abstract class LogInfo {
47	  public static final String ENTITY_FILE_NAME_DELIMITERS = "_.";
48	
49	  public String getAttemptDirName() {
50	    return attemptDirName;
51	  }
52	
53	  public long getOffset() {
54	    return offset;
55	  }
56	
57	  public void setOffset(long newOffset) {
58	    this.offset = newOffset;
59	  }
60	
61	  private String attemptDirName;
62	  private String filename;
63	  private String user;
64	  private long offset = 0;
65	
66	  private static final Logger LOG = LoggerFactory.getLogger(LogInfo.class);
67	
68	  public LogInfo(String attemptDirName, String file, String owner) {
69	    this.attemptDirName = attemptDirName;
70	    filename = file;
71	    user = owner;
72	  }
73	
74	  public Path getPath(Path rootPath) {
75	    Path attemptPath = new Path(rootPath, attemptDirName);
76	    return new Path(attemptPath, filename);
77	  }
78	
79	  public String getFilename() {
80	    return filename;
81	  }
82	
83	  public boolean matchesGroupId(TimelineEntityGroupId groupId) {
84	    return matchesGroupId(groupId.toString());
85	  }
86	
87	  @InterfaceAudience.Private
88	  @VisibleForTesting
89	  boolean matchesGroupId(String groupId){
90	    // Return true if the group id is a segment (separated by _, ., or end of
91	    // string) of the file name.
92	    int pos = filename.indexOf(groupId);
93	    if (pos < 0) {
94	      return false;
95	    }
96	    return filename.length() == pos + groupId.length()
97	        || ENTITY_FILE_NAME_DELIMITERS.contains(String.valueOf(
98	        filename.charAt(pos + groupId.length())
99	    ));
100	  }
101	
102	  public long parseForStore(TimelineDataManager tdm, Path appDirPath,
103	      boolean appCompleted, JsonFactory jsonFactory, ObjectMapper objMapper,
104	      FileSystem fs) throws IOException {
105	    LOG.debug("Parsing for log dir {} on attempt {}", appDirPath,
106	        attemptDirName);
107	    Path logPath = getPath(appDirPath);
108	    FileStatus status = fs.getFileStatus(logPath);
109	    long numParsed = 0;
110	    if (status != null) {
111	      long startTime = Time.monotonicNow();
112	      try {
113	        LOG.debug("Parsing {} at offset {}", logPath, offset);
114	        long count = parsePath(tdm, logPath, appCompleted, jsonFactory,
115	            objMapper, fs);
116	        LOG.info("Parsed {} entities from {} in {} msec",
117	            count, logPath, Time.monotonicNow() - startTime);
118	        numParsed += count;
119	      } catch (RuntimeException e) {
120	        // If AppLogs cannot parse this log, it may be corrupted or just empty
121	        if (e.getCause() instanceof JsonParseException &&
122	            (status.getLen() > 0 || offset > 0)) {
123	          // log on parse problems if the file as been read in the past or
124	          // is visibly non-empty
125	          LOG.info("Log {} appears to be corrupted. Skip. ", logPath);
126	        }
127	      }
128	    } else {
129	      LOG.warn("{} no longer exists. Skip for scanning. ", logPath);
130	    }
131	    return numParsed;
132	  }
133	
134	  private long parsePath(TimelineDataManager tdm, Path logPath,
135	      boolean appCompleted, JsonFactory jsonFactory, ObjectMapper objMapper,
136	      FileSystem fs) throws IOException {
137	    UserGroupInformation ugi =
138	        UserGroupInformation.createRemoteUser(user);
139	    FSDataInputStream in = fs.open(logPath);
140	    JsonParser parser = null;
141	    try {
142	      in.seek(offset);
143	      try {
144	        parser = jsonFactory.createParser((InputStream)in);
145	        parser.configure(JsonParser.Feature.AUTO_CLOSE_SOURCE, false);
146	      } catch (IOException e) {
147	        // if app hasn't completed then there may be errors due to the
148	        // incomplete file which are treated as EOF until app completes
149	        if (appCompleted) {
150	          throw e;
151	        } else {
152	          LOG.debug("Exception in parse path: {}", e.getMessage());
153	          return 0;
154	        }
155	      }
156	
157	      return doParse(tdm, parser, objMapper, ugi, appCompleted);
158	    } finally {
159	      IOUtils.closeStream(parser);
160	      IOUtils.closeStream(in);
161	    }
162	  }
163	
164	  protected abstract long doParse(TimelineDataManager tdm, JsonParser parser,
165	      ObjectMapper objMapper, UserGroupInformation ugi, boolean appCompleted)
166	      throws IOException;
167	}
168	
169	class EntityLogInfo extends LogInfo {
170	  private static final Logger LOG = LoggerFactory.getLogger(
171	      EntityGroupFSTimelineStore.class);
172	
173	  public EntityLogInfo(String attemptId,
174	      String file, String owner) {
175	    super(attemptId, file, owner);
176	  }
177	
178	  @Override
179	  protected long doParse(TimelineDataManager tdm, JsonParser parser,
180	      ObjectMapper objMapper, UserGroupInformation ugi, boolean appCompleted)
181	      throws IOException {
182	    long count = 0;
183	    TimelineEntities entities = new TimelineEntities();
184	    ArrayList<TimelineEntity> entityList = new ArrayList<TimelineEntity>(1);
185	    long bytesParsed;
186	    long bytesParsedLastBatch = 0;
187	    boolean postError = false;
188	    try {
189	      MappingIterator<TimelineEntity> iter = objMapper.readValues(parser,
190	          TimelineEntity.class);
191	
192	      while (iter.hasNext()) {
193	        TimelineEntity entity = iter.next();
194	        String etype = entity.getEntityType();
195	        String eid = entity.getEntityId();
196	        LOG.trace("Read entity {}", etype);
197	        ++count;
198	        bytesParsed = parser.getCurrentLocation().getCharOffset() + 1;
199	        LOG.trace("Parser now at offset {}", bytesParsed);
200	
201	        try {
202	          LOG.debug("Adding {}({}) to store", eid, etype);
203	          entityList.add(entity);
204	          entities.setEntities(entityList);
205	          TimelinePutResponse response = tdm.postEntities(entities, ugi);
206	          for (TimelinePutResponse.TimelinePutError e
207	              : response.getErrors()) {
208	            LOG.warn("Error putting entity: {} ({}): {}",
209	                e.getEntityId(), e.getEntityType(), e.getErrorCode());
210	          }
211	          setOffset(getOffset() + bytesParsed - bytesParsedLastBatch);
212	          bytesParsedLastBatch = bytesParsed;
213	          entityList.clear();
214	        } catch (YarnException e) {
215	          postError = true;
216	          throw new IOException("Error posting entities", e);
217	        } catch (IOException e) {
218	          postError = true;
219	          throw new IOException("Error posting entities", e);
220	        }
221	      }
222	    } catch (IOException e) {
223	      // if app hasn't completed then there may be errors due to the
224	      // incomplete file which are treated as EOF until app completes
225	      if (appCompleted || postError) {
226	        throw e;
227	      }
228	    } catch (RuntimeException e) {
229	      if (appCompleted || !(e.getCause() instanceof JsonParseException)) {
230	        throw e;
231	      }
232	    }
233	    return count;
234	  }
235	}
236	
237	class DomainLogInfo extends LogInfo {
238	  private static final Logger LOG = LoggerFactory.getLogger(
239	      EntityGroupFSTimelineStore.class);
240	
241	  public DomainLogInfo(String attemptDirName, String file,
242	      String owner) {
243	    super(attemptDirName, file, owner);
244	  }
245	
246	  protected long doParse(TimelineDataManager tdm, JsonParser parser,
247	      ObjectMapper objMapper, UserGroupInformation ugi, boolean appCompleted)
248	      throws IOException {
249	    long count = 0;
250	    long bytesParsed;
251	    long bytesParsedLastBatch = 0;
252	    boolean putError = false;
253	    try {
254	      MappingIterator<TimelineDomain> iter = objMapper.readValues(parser,
255	          TimelineDomain.class);
256	
257	      while (iter.hasNext()) {
258	        TimelineDomain domain = iter.next();
259	        domain.setOwner(ugi.getShortUserName());
260	        LOG.trace("Read domain {}", domain.getId());
261	        ++count;
262	        bytesParsed = parser.getCurrentLocation().getCharOffset() + 1;
263	        LOG.trace("Parser now at offset {}", bytesParsed);
264	
265	        try {
266	          tdm.putDomain(domain, ugi);
267	          setOffset(getOffset() + bytesParsed - bytesParsedLastBatch);
268	          bytesParsedLastBatch = bytesParsed;
269	        } catch (YarnException e) {
270	          putError = true;
271	          throw new IOException("Error posting domain", e);
272	        } catch (IOException e) {
273	          putError = true;
274	          throw new IOException("Error posting domain", e);
275	        }
276	      }
277	    } catch (IOException e) {
278	      // if app hasn't completed then there may be errors due to the
279	      // incomplete file which are treated as EOF until app completes
280	      if (appCompleted || putError) {
281	        throw e;
282	      }
283	    } catch (RuntimeException e) {
284	      if (appCompleted || !(e.getCause() instanceof JsonParseException)) {
285	        throw e;
286	      }
287	    }
288	    return count;
289	  }
290	}
