215	  private List<TimelineEntityGroupPlugin> loadPlugIns(Configuration conf)
216	      throws RuntimeException {
217	    Collection<String> pluginNames = conf.getTrimmedStringCollection(
218	        YarnConfiguration.TIMELINE_SERVICE_ENTITY_GROUP_PLUGIN_CLASSES);
219	
220	    String pluginClasspath = conf.getTrimmed(
221	        YarnConfiguration.TIMELINE_SERVICE_ENTITY_GROUP_PLUGIN_CLASSPATH);
222	    String[] systemClasses = conf.getTrimmedStrings(
223	        YarnConfiguration.TIMELINE_SERVICE_ENTITY_GROUP_PLUGIN_SYSTEM_CLASSES);
224	
225	    List<TimelineEntityGroupPlugin> pluginList
226	        = new LinkedList<TimelineEntityGroupPlugin>();
227	    ClassLoader customClassLoader = null;
228	    if (pluginClasspath != null && pluginClasspath.length() > 0) {
229	      try {
230	        customClassLoader = createPluginClassLoader(pluginClasspath,
231	            systemClasses);
232	      } catch (IOException ioe) {
233	        LOG.warn("Error loading classloader", ioe);
234	      }
235	    }
236	    for (final String name : pluginNames) {
237	      LOG.debug("Trying to load plugin class {}", name);
238	      TimelineEntityGroupPlugin cacheIdPlugin = null;
239	
240	      try {
241	        if (customClassLoader != null) {
242	          LOG.debug("Load plugin {} with classpath: {}", name, pluginClasspath);
243	          Class<?> clazz = Class.forName(name, true, customClassLoader);
244	          Class<? extends TimelineEntityGroupPlugin> sClass = clazz.asSubclass(
245	              TimelineEntityGroupPlugin.class);
246	          cacheIdPlugin = ReflectionUtils.newInstance(sClass, conf);
247	        } else {
248	          LOG.debug("Load plugin class with system classpath");
249	          Class<?> clazz = conf.getClassByName(name);
250	          cacheIdPlugin =
251	              (TimelineEntityGroupPlugin) ReflectionUtils.newInstance(
252	                  clazz, conf);
253	        }
254	      } catch (Exception e) {
255	        LOG.warn("Error loading plugin " + name, e);
256	        throw new RuntimeException("No class defined for " + name, e);
257	      }
258	
259	      LOG.info("Load plugin class {}", cacheIdPlugin.getClass().getName());
260	      pluginList.add(cacheIdPlugin);
261	    }
262	    return pluginList;
263	  }
