331	    LOG.info("Stopping {}", getName());
332	    stopExecutors.set(true);
333	    if (executor != null) {
334	      executor.shutdown();
335	      if (executor.isTerminating()) {
336	        LOG.info("Waiting for executor to terminate");
337	        boolean terminated = executor.awaitTermination(10, TimeUnit.SECONDS);
338	        if (terminated) {
339	          LOG.info("Executor terminated");
340	        } else {
341	          LOG.warn("Executor did not terminate");
342	          executor.shutdownNow();
343	        }
344	      }
345	    }
346	    synchronized (cachedLogs) {
347	      for (EntityCacheItem cacheItem : cachedLogs.values()) {
348	        ServiceOperations.stopQuietly(cacheItem.getStore());
349	      }
350	    }
351	    CallerContext.setCurrent(null);
352	    super.serviceStop();
353	  }
