364	  int scanActiveLogs(Path dir) throws IOException {
365	    RemoteIterator<FileStatus> iter = list(dir);
366	    int logsToScanCount = 0;
367	    while (iter.hasNext()) {
368	      FileStatus stat = iter.next();
369	      String name = stat.getPath().getName();
370	      ApplicationId appId = parseApplicationId(name);
371	      if (appId != null) {
372	        LOG.debug("scan logs for {} in {}", appId, stat.getPath());
373	        logsToScanCount++;
374	        AppLogs logs = getAndSetActiveLog(appId, stat.getPath());
375	        executor.execute(new ActiveLogParser(logs));
376	      } else {
377	        if (stat.isDirectory()) {
378	          logsToScanCount += scanActiveLogs(stat.getPath());
379	        } else {
380	          LOG.warn("Ignoring unexpected file in active directory {}",
381	              stat.getPath());
382	        }
383	      }
384	    }
385	    return logsToScanCount;
386	  }
