399	  private AppLogs createAndPutAppLogsIfAbsent(ApplicationId appId,
400	      Path appDirPath, AppState appState) {
401	    AppLogs appLogs = new AppLogs(appId, appDirPath, appState);
402	    AppLogs oldAppLogs = appIdLogMap.putIfAbsent(appId, appLogs);
