409	  private AppLogs getAndSetActiveLog(ApplicationId appId, Path appDirPath) {
410	    AppLogs appLogs = appIdLogMap.get(appId);
411	    if (appLogs == null) {
412	      appLogs = createAndPutAppLogsIfAbsent(appId, appDirPath, AppState.ACTIVE);
413	    }
414	    return appLogs;
415	  }
