417	  // searches for the app logs and returns it if found else null
418	  private AppLogs getAndSetAppLogs(ApplicationId applicationId)
419	      throws IOException {
420	    LOG.debug("Looking for app logs mapped for app id {}", applicationId);
421	    AppLogs appLogs = appIdLogMap.get(applicationId);
422	    if (appLogs == null) {
423	      AppState appState = AppState.UNKNOWN;
424	      Path appDirPath = getDoneAppPath(applicationId);
425	      if (fs.exists(appDirPath)) {
426	        appState = AppState.COMPLETED;
427	      } else {
428	        appDirPath = getActiveAppPath(applicationId);
429	        if (fs.exists(appDirPath)) {
430	          appState = AppState.ACTIVE;
431	        } else {
432	          // check for user directory inside active path
433	          RemoteIterator<FileStatus> iter = list(activeRootPath);
434	          while (iter.hasNext()) {
435	            Path child = new Path(iter.next().getPath().getName(),
436	                applicationId.toString());
437	            appDirPath = new Path(activeRootPath, child);
438	            if (fs.exists(appDirPath)) {
439	              appState = AppState.ACTIVE;
440	              break;
441	            }
442	          }
443	        }
444	      }
445	      if (appState != AppState.UNKNOWN) {
446	        LOG.debug("Create and try to add new appLogs to appIdLogMap for {}",
447	            applicationId);
448	        appLogs = createAndPutAppLogsIfAbsent(
449	            applicationId, appDirPath, appState);
450	      }
451	    }
452	    return appLogs;
453	  }
