455	  /**
456	   * Main function for entity log cleaner. This method performs depth first
457	   * search from a given dir path for all application log dirs. Once found, it
458	   * will decide if the directory should be cleaned up and then clean them.
459	   *
460	   * @param dirpath the root directory the cleaner should start with. Note that
461	   *                dirpath should be a directory that contains a set of
462	   *                application log directories. The cleaner method will not
463	   *                work if the given dirpath itself is an application log dir.
464	   * @param retainMillis
465	   * @throws IOException
466	   */
467	  @InterfaceAudience.Private
468	  @VisibleForTesting
469	  void cleanLogs(Path dirpath, long retainMillis)
470	      throws IOException {
471	    long now = Time.now();
472	    RemoteIterator<FileStatus> iter = list(dirpath);
473	    while (iter.hasNext()) {
474	      FileStatus stat = iter.next();
475	      if (isValidClusterTimeStampDir(stat)) {
476	        Path clusterTimeStampPath = stat.getPath();
477	        MutableBoolean appLogDirPresent = new MutableBoolean(false);
478	        cleanAppLogDir(clusterTimeStampPath, retainMillis, appLogDirPresent);
479	        if (appLogDirPresent.isFalse() &&
480	            (now - stat.getModificationTime() > retainMillis)) {
481	          deleteDir(clusterTimeStampPath);
482	        }
483	      }
484	    }
485	  }
486	
487	
488	  private void cleanAppLogDir(Path dirpath, long retainMillis,
489	      MutableBoolean appLogDirPresent) throws IOException {
490	    long now = Time.now();
491	    // Depth first search from root directory for all application log dirs
492	    RemoteIterator<FileStatus> iter = list(dirpath);
493	    while (iter.hasNext()) {
494	      FileStatus stat = iter.next();
495	      Path childPath = stat.getPath();
496	      if (stat.isDirectory()) {
497	        // If current is an application log dir, decide if we need to remove it
498	        // and remove if necessary.
499	        // Otherwise, keep iterating into it.
500	        ApplicationId appId = parseApplicationId(childPath.getName());
501	        if (appId != null) { // Application log dir
502	          appLogDirPresent.setTrue();
503	          if (shouldCleanAppLogDir(childPath, now, fs, retainMillis)) {
504	            deleteDir(childPath);
505	          }
506	        } else { // Keep cleaning inside
507	          cleanAppLogDir(childPath, retainMillis, appLogDirPresent);
508	        }
509	      }
510	    }
511	  }
512	
513	  private void deleteDir(Path path) {
514	    try {
515	      LOG.info("Deleting {}", path);
516	      if (fs.delete(path, true)) {
517	        metrics.incrLogsDirsCleaned();
518	      } else {
519	        LOG.error("Unable to remove {}", path);
520	      }
521	    } catch (IOException e) {
522	      LOG.error("Unable to remove {}", path, e);
523	    }
524	  }
525	
526	  private boolean isValidClusterTimeStampDir(FileStatus stat) {
527	    return stat.isDirectory() &&
528	        StringUtils.isNumeric(stat.getPath().getName());
529	  }
530	
531	
532	  private static boolean shouldCleanAppLogDir(Path appLogPath, long now,
533	      FileSystem fs, long logRetainMillis) throws IOException {
534	    RemoteIterator<FileStatus> iter = fs.listStatusIterator(appLogPath);
535	    while (iter.hasNext()) {
536	      FileStatus stat = iter.next();
537	      if (now - stat.getModificationTime() <= logRetainMillis) {
538	        // found a dir entry that is fresh enough to prevent
539	        // cleaning this directory.
540	        LOG.debug("{} not being cleaned due to {}", appLogPath, stat.getPath());
541	        return false;
542	      }
543	      // Otherwise, keep searching files inside for directories.
544	      if (stat.isDirectory()) {
545	        if (!shouldCleanAppLogDir(stat.getPath(), now, fs, logRetainMillis)) {
546	          return false;
547	        }
548	      }
549	    }
550	    return true;
551	  }
