562	  private static ClassLoader createPluginClassLoader(
563	      final String appClasspath, final String[] systemClasses)
564	      throws IOException {
565	    try {
566	      return AccessController.doPrivileged(
567	        new PrivilegedExceptionAction<ClassLoader>() {
568	          @Override
569	          public ClassLoader run() throws MalformedURLException {
570	            return new ApplicationClassLoader(appClasspath,
571	                EntityGroupFSTimelineStore.class.getClassLoader(),
572	                Arrays.asList(systemClasses));
573	          }
574	        }
575	      );
576	    } catch (PrivilegedActionException e) {
577	      Throwable t = e.getCause();
578	      if (t instanceof MalformedURLException) {
579	        throw (MalformedURLException) t;
580	      }
581	      throw new IOException(e);
582	    }
583	  }
