709	    @InterfaceAudience.Private
710	    @VisibleForTesting
711	    synchronized void parseSummaryLogs(TimelineDataManager tdm)
712	        throws IOException {
713	      long startTime = Time.monotonicNow();
714	      if (!isDone()) {
715	        LOG.debug("Try to parse summary log for log {} in {}",
716	            appId, appDirPath);
717	        appState = getAppState(appId);
718	        long recentLogModTime = scanForLogs();
719	        if (appState == AppState.UNKNOWN) {
720	          if (Time.now() - recentLogModTime > unknownActiveMillis) {
721	            LOG.info(
722	                "{} state is UNKNOWN and logs are stale, assuming COMPLETED",
723	                appId);
724	            appState = AppState.COMPLETED;
725	          }
726	        }
727	      }
728	      List<LogInfo> removeList = new ArrayList<LogInfo>();
729	      for (LogInfo log : summaryLogs) {
730	        if (fs.exists(log.getPath(appDirPath))) {
731	          long summaryEntityParsed
732	              = log.parseForStore(tdm, appDirPath, isDone(), jsonFactory,
733	              objMapper, fs);
734	          metrics.incrEntitiesReadToSummary(summaryEntityParsed);
735	        } else {
736	          // The log may have been removed, remove the log
737	          removeList.add(log);
738	          LOG.info("File {} no longer exists, remove it from log list",
739	              log.getPath(appDirPath));
740	        }
741	      }
742	      summaryLogs.removeAll(removeList);
743	      metrics.addSummaryLogReadTime(Time.monotonicNow() - startTime);
744	    }
745	
746	    // scans for new logs and returns the modification timestamp of the
747	    // most recently modified log
748	    @InterfaceAudience.Private
749	    @VisibleForTesting
750	    long scanForLogs() throws IOException {
751	      LOG.debug("scanForLogs on {}", appDirPath);
752	      long newestModTime = 0;
753	      RemoteIterator<FileStatus> iterAttempt = list(appDirPath);
754	      while (iterAttempt.hasNext()) {
755	        FileStatus statAttempt = iterAttempt.next();
756	        LOG.debug("scanForLogs on {}", statAttempt.getPath().getName());
757	        if (!statAttempt.isDirectory()
758	            || !statAttempt.getPath().getName()
759	            .startsWith(ApplicationAttemptId.appAttemptIdStrPrefix)) {
760	          LOG.debug("Scanner skips for unknown dir/file {}",
761	              statAttempt.getPath());
762	          continue;
763	        }
764	        String attemptDirName = statAttempt.getPath().getName();
765	        RemoteIterator<FileStatus> iterCache = list(statAttempt.getPath());
766	        while (iterCache.hasNext()) {
767	          FileStatus statCache = iterCache.next();
768	          if (!statCache.isFile()) {
769	            continue;
770	          }
771	          String filename = statCache.getPath().getName();
772	          String owner = statCache.getOwner();
773	          //YARN-10884:Owner of File is set to Null on WASB Append Operation.ATS fails to read such
774	          //files as UGI cannot be constructed using Null User.To Fix this,anonymous user is set
775	          //when ACL us Disabled as the UGI is not needed there
776	          if ((owner == null || owner.isEmpty()) && !aclsEnabled) {
777	            LOG.debug("The owner was null when acl disabled, hence making the owner anonymous");
778	            owner = "anonymous";
779	          }
780	          // We should only update time for log files.
781	          boolean shouldSetTime = true;
782	          LOG.debug("scan for log file: {}", filename);
783	          if (filename.startsWith(DOMAIN_LOG_PREFIX)) {
784	            addSummaryLog(attemptDirName, filename, owner, true);
785	          } else if (filename.startsWith(SUMMARY_LOG_PREFIX)) {
786	            addSummaryLog(attemptDirName, filename, owner,
787	                false);
788	          } else if (filename.startsWith(ENTITY_LOG_PREFIX)) {
789	            addDetailLog(attemptDirName, filename, owner);
790	          } else {
791	            shouldSetTime = false;
792	          }
793	          if (shouldSetTime) {
794	            newestModTime
795	              = Math.max(statCache.getModificationTime(), newestModTime);
796	          }
797	        }
798	      }
799	
800	      // if there are no logs in the directory then use the modification
801	      // time of the directory itself
802	      if (newestModTime == 0) {
803	        newestModTime = fs.getFileStatus(appDirPath).getModificationTime();
804	      }
805	
806	      return newestModTime;
807	    }
808	
809	    private void addSummaryLog(String attemptDirName,
810	        String filename, String owner, boolean isDomainLog) {
811	      for (LogInfo log : summaryLogs) {
812	        if (log.getFilename().equals(filename)
813	            && log.getAttemptDirName().equals(attemptDirName)) {
814	          return;
815	        }
816	      }
817	      LOG.debug("Incoming log {} not present in my summaryLogs list, add it",
818	          filename);
819	      LogInfo log;
820	      if (isDomainLog) {
821	        log = new DomainLogInfo(attemptDirName, filename, owner);
822	        summaryLogs.add(0, log);
823	      } else {
824	        log = new EntityLogInfo(attemptDirName, filename, owner);
825	        summaryLogs.add(log);
826	      }
827	    }
828	
829	    private synchronized void addDetailLog(String attemptDirName,
830	        String filename, String owner) {
831	      for (LogInfo log : detailLogs) {
832	        if (log.getFilename().equals(filename)
833	            && log.getAttemptDirName().equals(attemptDirName)) {
834	          return;
835	        }
836	      }
837	      detailLogs.add(new EntityLogInfo(attemptDirName, filename, owner));
838	    }
