1042	  // find a cached timeline store or null if it cannot be located
1043	  private TimelineStore getCachedStore(TimelineEntityGroupId groupId,
1044	      List<EntityCacheItem> cacheItems) throws IOException {
1045	    EntityCacheItem cacheItem;
1046	    synchronized (this.cachedLogs) {
1047	      // Note that the content in the cache log storage may be stale.
1048	      cacheItem = this.cachedLogs.get(groupId);
1049	      if (cacheItem == null) {
1050	        LOG.debug("Set up new cache item for id {}", groupId);
1051	        cacheItem = new EntityCacheItem(groupId, getConfig());
1052	        AppLogs appLogs = getAndSetAppLogs(groupId.getApplicationId());
1053	        if (appLogs != null) {
1054	          LOG.debug("Set applogs {} for group id {}", appLogs, groupId);
1055	          cacheItem.setAppLogs(appLogs);
1056	          this.cachedLogs.put(groupId, cacheItem);
1057	        } else {
1058	          LOG.warn("AppLogs for groupId {} is set to null!", groupId);
1059	        }
1060	      }
1061	    }
1062	    TimelineStore store = null;
1063	    if (cacheItem.getAppLogs() != null) {
1064	      AppLogs appLogs = cacheItem.getAppLogs();
1065	      LOG.debug("try refresh cache {} {}", groupId, appLogs.getAppId());
1066	      cacheItems.add(cacheItem);
1067	      store = cacheItem.refreshCache(aclManager, metrics);
1068	    } else {
1069	      LOG.warn("AppLogs for group id {} is null", groupId);
1070	    }
1071	    return store;
1072	  }
