302	  @Test
303	  public void testCleanLogs() throws Exception {
304	    // Create test dirs and files
305	    // Irrelevant file, should not be reclaimed
306	    String appDirName = mainTestAppId.toString();
307	    String attemptDirName = ApplicationAttemptId.appAttemptIdStrPrefix
308	        + appDirName + "_1";
309	    Path irrelevantFilePath = new Path(
310	            testDoneDirPath, "irrelevant.log");
311	    FSDataOutputStream stream = fs.create(irrelevantFilePath);
312	    stream.close();
313	    // Irrelevant directory, should not be reclaimed
314	    Path irrelevantDirPath = new Path(testDoneDirPath, "irrelevant");
315	    fs.mkdirs(irrelevantDirPath);
316	
317	    Path doneAppHomeDir = new Path(new Path(new Path(testDoneDirPath,
318	        Long.toString(mainTestAppId.getClusterTimestamp())), "0000"), "001");
319	    // First application, untouched after creation
320	    Path appDirClean = new Path(doneAppHomeDir, appDirName);
321	    Path attemptDirClean = new Path(appDirClean, attemptDirName);
322	    fs.mkdirs(attemptDirClean);
323	    Path filePath = new Path(attemptDirClean, "test.log");
324	    stream = fs.create(filePath);
325	    stream.close();
326	    // Second application, one file touched after creation
327	    Path appDirHoldByFile = new Path(doneAppHomeDir, appDirName + "1");
328	    Path attemptDirHoldByFile
329	        = new Path(appDirHoldByFile, attemptDirName);
330	    fs.mkdirs(attemptDirHoldByFile);
331	    Path filePathHold = new Path(attemptDirHoldByFile, "test1.log");
332	    stream = fs.create(filePathHold);
333	    stream.close();
334	    // Third application, one dir touched after creation
335	    Path appDirHoldByDir = new Path(doneAppHomeDir, appDirName + "2");
336	    Path attemptDirHoldByDir = new Path(appDirHoldByDir, attemptDirName);
337	    fs.mkdirs(attemptDirHoldByDir);
338	    Path dirPathHold = new Path(attemptDirHoldByDir, "hold");
339	    fs.mkdirs(dirPathHold);
340	    // Fourth application, empty dirs
341	    Path appDirEmpty = new Path(doneAppHomeDir, appDirName + "3");
342	    Path attemptDirEmpty = new Path(appDirEmpty, attemptDirName);
343	    fs.mkdirs(attemptDirEmpty);
344	    Path dirPathEmpty = new Path(attemptDirEmpty, "empty");
345	    fs.mkdirs(dirPathEmpty);
346	
347	    // Should retain all logs after this run
348	    MutableCounterLong dirsCleaned = store.metrics.getLogsDirsCleaned();
349	    long before = dirsCleaned.value();
350	    store.cleanLogs(testDoneDirPath, 10000);
351	    assertTrue(fs.exists(irrelevantDirPath));
352	    assertTrue(fs.exists(irrelevantFilePath));
353	    assertTrue(fs.exists(filePath));
354	    assertTrue(fs.exists(filePathHold));
355	    assertTrue(fs.exists(dirPathHold));
356	    assertTrue(fs.exists(dirPathEmpty));
357	
358	    // Make sure the created dir is old enough
359	    Thread.sleep(2000);
360	    // Touch the second application
361	    stream = fs.append(filePathHold);
362	    stream.writeBytes("append");
363	    stream.close();
364	    // Touch the third application by creating a new dir
365	    fs.mkdirs(new Path(dirPathHold, "holdByMe"));
366	
367	    store.cleanLogs(testDoneDirPath, 1000);
368	
369	    // Verification after the second cleaner call
370	    assertTrue(fs.exists(irrelevantDirPath));
371	    assertTrue(fs.exists(irrelevantFilePath));
372	    assertTrue(fs.exists(filePathHold));
373	    assertTrue(fs.exists(dirPathHold));
374	    assertTrue(fs.exists(doneAppHomeDir));
375	
376	    // appDirClean and appDirEmpty should be cleaned up
377	    assertFalse(fs.exists(appDirClean));
378	    assertFalse(fs.exists(appDirEmpty));
379	    assertEquals(before + 2L, dirsCleaned.value());
380	  }
